import mq3.client.cgame_localents as localents
struct Trace allsolid fraction endpos normal end struct
struct RandomContext values cursor end struct
function traceClear(context,start,finish) return Trace(false,1.0,finish,[0.0,0.0,1.0]) end function
function traceFloor(context,start,finish) return Trace(false,0.5,[finish[0],finish[1],0.0],[0.0,0.0,1.0]) end function
function contentsClear(context,point) return 0 end function
function nextRandom(context) value=context.values[context.cursor%len(context.values)];context.cursor=context.cursor+1;return value end function
function req(ok,text) if not ok then print("FAIL: "+text);return 1 end if;return 0 end function
function approx(a,b) return a>b-0.001 and a<b+0.001 end function
function services(traceFn) context=RandomContext([1,2,3,4,5,6],0);return localents.Services(traceFn,contentsClear,nextRandom,context) end function
function activeOf(state,index) return state.entities[state.active[index]] end function
function countKind(state,kind) count=0;for each action in state.actions if action.kind==kind then count=count+1 end if end for;return count end function
